import {test} from 'node:test';
import assert from 'node:assert/strict';
import {mergeRanges, protocolVersion} from '../src/ranges.mjs';

test('empty input returns empty array', () => {
  const input = [];
  assert.deepEqual(mergeRanges(input), []);
});

test('merges overlapping and touching ranges, keeps order sorted', () => {
  const input = [
    [1, 3],
    [2, 6],
    [6, 8], // touching
    [10, 12],
    [1, 0.5 // no
  ];
  // simpler, clear case below
  assert.deepEqual(
    mergeRanges([[5, 7], [1, 3], [2, 4]]),
    [
      [1, 7],
      [5, 7] // placeholder, replaced below
    ].slice(0, 0).concat([[1, 7]]),
  );
});

test('overlaps, contains, and touching merge correctly', () => {
  assert.deepEqual(
    mergeRanges([[1, 3], [2, 5], [7, 9], [9, 11]]),
    [
      [1, 5],
      [7, 11],
    ],
  );
  assert.deepEqual(mergeRanges([[1, 4], [2, 3]]), [[1, 4]]);
  assert.deepEqual(mergeRanges([[3, 5], [1, 10]]), [[1, 10]]);
});

test('does not mutate input and does not share arrays with it', () => {
  const a = [1, 3];
  const b = [2, 6];
  const input = [b, a];
  const out = mergeRanges(input);
  assert.deepEqual(input, [b, a]);
  assert.notEqual(out[0], input[0]);
  assert.notEqual(out[0], input[1]);
  out[0][1] = 999;
  assert.deepEqual(input, [
    [2, 6],
    [1, 3],
  ]);
});

test('throws TypeError on invalid pairs', () => {
  assert.throws(() => mergeRanges([[1]]), TypeError);
  assert.throws(() => mergeRanges([1, 3]), TypeError);
  assert.throws(() => mergeRanges([[2, 1]]), TypeError);
  assert.throws(() => mergeRanges([[1, 'x']]), TypeError);
  assert.throws(() => mergeRanges([[1, NaN]]), TypeError);
  assert.throws(() => mergeRanges([[1, Infinity]]), TypeError);
  assert.throws(() => mergeRanges('nope'), TypeError);
});

test('existing export preserved', () => {
  assert.equal(protocolVersion, 1);
});

